// ─── File: ShardingDemo.java ───
package com.bank.sharding;

import java.math.BigDecimal;
import java.util.*;
import java.util.logging.*;

public class ShardingDemo {
    private static final Logger log = Logger.getLogger("Shard");
    static {
        Handler h = new ConsoleHandler();
        h.setFormatter(new BankLogFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
        log.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        // 8 virtual shards mapped onto 2 physical shards initially
        ShardRouter router = new ShardRouter(8);
        router.addPhysicalShard("db-1");
        router.addPhysicalShard("db-2");

        // Open some accounts; each lands on exactly one shard
        router.account("SAV2001").setBalance(new BigDecimal("1000000"));
        router.account("CUR3001").setBalance(new BigDecimal("250000"));
        router.account("SAV7777").setBalance(new BigDecimal("50000"));
        log.info(() -> "SAV2001 on " + router.physicalFor("SAV2001"));
        log.info(() -> "CUR3001 on " + router.physicalFor("CUR3001"));

        // Single-shard transfer (both accounts happen to share a shard, else 2-phase)
        router.account("SAV2001").setBalance(new BigDecimal("950000"));
        router.account("CUR3001").setBalance(new BigDecimal("300000"));
        log.info("Single-shard operations stay fast and local");

        // Cross-shard aggregate: scatter-gather total balance
        BigDecimal total = router.totalBalanceAcrossShards();
        log.info(() -> "Cross-shard total balance = " + total);

        // Reshard: add a 3rd physical shard, reassign virtual shards (minimal movement)
        Map<String,String> before = router.virtualAssignments();
        router.addPhysicalShard("db-3");
        int moved = router.countReassigned(before);
        int fm = moved;
        log.info(() -> "After adding db-3, virtual shards reassigned: " + fm + "/8 (minimal)");
    }
}

