// ─── File: Shard.java ───
package com.bank.sharding;

import java.math.BigDecimal;
import java.util.*;

// One physical database instance holding a slice of accounts.
public class Shard {
    private final String name;
    private final Map<String, Account> accounts = new HashMap<>();
    public Shard(String name) { this.name = name; }
    public String name() { return name; }
    public Account account(String id) { return accounts.computeIfAbsent(id, Account::new); }
    public BigDecimal sumBalances() {
        return accounts.values().stream().map(Account::getBalance)
            .reduce(BigDecimal.ZERO, BigDecimal::add);
    }
}
